mapper.select:
SELECT  FROM sys_role

    status != 3
    AND (name LIKE CONCAT(#{keyword}, '%') OR code LIKE CONCAT(#{keyword}, '%'))
    AND status = #{status}

ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE sys_role SET status = #{status}, updated_at = NOW(),
                    deleted_at = (CASE WHEN #{status} = 3 THEN NOW() ELSE deleted_at END)
WHERE id = #{id}
